// Check 08 (#995 gap 2, G16-adapter-mounts call 3): `ortho prove` stands up each mount's process stand-in, hands the Worker its
// address and a key of the mount's own, and stops it, and all it started, when the world ends.
//
// Four adapters are generated by the real command (`ortho new adapter <name> --from-openapi`) into a copy of acme and mounted:
// `rates` as `pricing` and `fx-rates` as `fx-backup`, each `Stand.process(...)` in its `src/written.ts` with `orthograph.standIn`
// naming a stand-in this check writes (`stand.mjs`); `open`, `Stand.none`, and `sandbox`, `Stand.vendor(...)`, whose packages
// name a stand-in all the same, so a build that starts whatever a package names, not what the model says, is seen. The stand-in is a small Node server: it writes
// what it was given and every request to a log this check reads (its path is written into the file, so it needs nothing from
// the environment prove gives it), starts a process of its own that it never stops, and says `stand-in listening on <url>`.
//
// The contract judged (G16-adapter-mounts call 3, the one `e2e/superagent/servers.ts` holds):
//  - a world prove starts runs `node <entry> --port 0 --dir <the world's state>/stands/<mount>` once for each mount whose
//    adapter's stand-in is a process, the folder there when it starts, and none for any other (`none` or `vendor`);
//  - the Worker gets `ORTHO_STAND_<MOUNT>` = the address the stand-in said and `<MOUNT>_API_KEY` = `world-<mount>`, so a call step
//    on the mount reaches the stand-in with that key, two mounts with two keys (this test also needs gap 1's call steps,
//    G16-adapter-mounts call 1);
//  - when the world ends prove stops each stand-in and every process it started: none is left once prove has exited;
//  - a stand-in that exits (with any code) before it says where it listens fails prove at once, not after the 60 s wait; one
//    that says nothing within 60 s fails prove too. Each names the mount and leaves nothing running; a stand-in that
//    ignores SIGTERM is stopped all the same;
//  - the stand-in runs in its package's folder, and prove keeps reading what it says after its line;
//  - a model with a process stand-in makes prove take a world of its own, as a device chain does: a warm `ortho dev` world,
//    which has no stand-ins, is not reused (m1 check 30 is the control: without one, it is).
//
// Real workerd, a port from the OS. Written by the checks author; a builder never edits this file.
import { spawn, spawnSync, type ChildProcess } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, readdirSync, realpathSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { createServer } from "node:net";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { acme, cli, copyOf, nothingRunning } from "../layer1/support.ts";

// ---- the descriptions the adapters are generated from ----

const spec = (title: string) => ({
  openapi: "3.0.3",
  info: { title, version: "1.0.0" },
  // A production server that never resolves: a build that sends there instead of to the stand-in leaves the world.
  servers: [{ url: `https://${title.toLowerCase()}.example.invalid/v1` }],
  components: { securitySchemes: { bearer: { type: "http", scheme: "bearer" } } },
  security: [{ bearer: [] }],
  paths: {
    "/quotes/{pair}": {
      get: {
        operationId: "quotes/get",
        parameters: [
          { name: "pair", in: "path", required: true, schema: { type: "string" } },
          { name: "amount", in: "query", required: true, schema: { type: "integer" } },
        ],
        responses: { "200": { description: "A quote", content: { "application/json": { schema: {
          type: "object", required: ["pair", "rate"], properties: { pair: { type: "string" }, rate: { type: "string" } } } } } } },
      },
    },
  },
});

// ---- the stand-in ----

/**
 * The stand-in for `plugin`, writing to `log`. It behaves as a real one may, so a build that leans on a tidy one is seen: it says
 * other things first, waits, and says its line in two writes split mid-line; it then writes a megabyte to stdout and stderr each
 * (Linux pipes block, so a build that stops reading after the line stalls it); and it and its child ignore SIGTERM. `refuse`
 * makes it exit with that code before it listens; `silent`, listen and never say where.
 */
type Fault = { readonly refuse: number } | { readonly silent: true };
const standInOf = (plugin: string, log: string, fault?: Fault) => `// A stand-in written by check 08.
import { appendFileSync, existsSync } from "node:fs";
import { createServer } from "node:http";
import { spawn } from "node:child_process";

const write = (entry) => appendFileSync(${JSON.stringify(log)}, JSON.stringify({ plugin: ${JSON.stringify(plugin)}, ...entry }) + "\\n");
const args = process.argv.slice(2);
const dir = args.includes("--dir") ? args[args.indexOf("--dir") + 1] : undefined;
${fault !== undefined && "refuse" in fault ? `write({ event: "refused", pid: process.pid });\nprocess.exit(${fault.refuse});\n` : ""}process.on("SIGTERM", () => {});
// A process of its own, never stopped by this stand-in, which also ignores SIGTERM: prove stops everything a stand-in started.
const child = spawn(process.execPath, ["-e", "process.on('SIGTERM', () => {}); setInterval(() => {}, 1 << 30)"], { stdio: "ignore" });
write({ event: "start", args, cwd: process.cwd(), pid: process.pid, child: child.pid, dirThere: dir !== undefined && existsSync(dir) });
const server = createServer((request, response) => {
  write({ event: "request", method: request.method, url: request.url, authorization: request.headers.authorization ?? null, dirThere: dir !== undefined && existsSync(dir) });
  const pair = /\\/quotes\\/([^/?]+)/.exec(request.url ?? "")?.[1];
  response.writeHead(200, { "content-type": "application/json" });
  response.end(JSON.stringify({ pair, rate: ${JSON.stringify(`${plugin}-stand-1.0842`)} }));
});
const port = args.includes("--port") ? Number(args[args.indexOf("--port") + 1]) : 0;
server.listen(port, "127.0.0.1", () => {
  process.stdout.write("${plugin} stand-in: loading fixtures\\n");
  process.stderr.write("${plugin} stand-in: a warning on stderr\\n");
  setTimeout(() => {
${fault !== undefined && "silent" in fault ? '    write({ event: "silent", pid: process.pid });\n' : `    process.stdout.write("stand-in listening on http://127.0");
    setTimeout(() => {
      process.stdout.write(".0.1:" + server.address().port + "\\n");
      const filler = ".".repeat(1023) + "\\n";
      for (let i = 0; i < 1024; i++) { process.stdout.write(filler); process.stderr.write(filler); }
      write({ event: "flooded" });
    }, 300);
`}  }, 2500);
});
`;

// ---- the app ----

const THING = `import { Blueprint } from "orthograph";

export const Rate = Blueprint.thing({ description: "A rate asked of a mounted adapter.", fields: { id: Blueprint.id("rte") }, code: "RT" });
`;
const mountOf = (name: string) => `import { Blueprint } from "orthograph";
import adapter from "@orthograph/${name}";

export default Blueprint.use(adapter, (a) => [a.include(a.calls.quotes.get)]);
`;
const pascalOf = (name: string) => name.split("-").map((w) => w[0]!.toUpperCase() + w.slice(1)).join("");
const FOUR = ["ApiFailure", "InputRefused", "AnswerRefused", "Unreachable"] as const;
/** An operation calling `quotes.get` on `mount`, declaring the adapter's four errors (G16-adapter-mounts call 1). */
const verbOf = (mount: string, pkg: string) => {
  const four = FOUR.map((f) => `${pascalOf(pkg)}${f}`);
  return `import { Blueprint } from "orthograph";
import { ${four.join(", ")} } from "@orthograph/${pkg}";
import adapter from "../../../adapters/${mount}.ts";
import { Rate } from "../thing.ts";

export default Blueprint.operation(Rate, {
  description: "Ask the ${mount} mount for a rate.",
  payload: { pair: Blueprint.text({ max: 20 }), amount: Blueprint.uint(32) },
  answer: { rate: Blueprint.text({ max: 40 }) },
  errors: [${four.join(", ")}],
  allowed: [Blueprint.anyone],
  steps: { price: Blueprint.step.call(adapter.calls.quotes.get) },
});
`;
};
/** The handler: the call's one input object; any failure is the adapter's Unreachable (the check reads only answers). */
const handlerOf = (verb: string, pkg: string) => `import { Effect } from "effect";
import { ${pascalOf(pkg)}Unreachable } from "@orthograph/${pkg}";
import type { Handler } from "../../generated/server/handlers/rate/${verb}.ts";

const handler = ((payload: { readonly pair: string; readonly amount: bigint | number | string }, { steps }: { readonly steps: Record<string, (...args: ReadonlyArray<unknown>) => Effect.Effect<unknown, unknown>> }) =>
  steps["price"]!([{ pair: payload.pair, amount: Number(payload.amount) }], () => new ${pascalOf(pkg)}Unreachable({} as never)).pipe(
    Effect.map((answer) => ({ rate: String((answer as { readonly rate?: unknown }).rate) })),
  )) as unknown as Handler;

export default handler;
`;
const JOURNEY = `import { Blueprint, expect } from "orthograph";
import backup from "../blueprint/things/rate/verbs/backup.ts";
import quote from "../blueprint/things/rate/verbs/quote.ts";

export default Blueprint.journey("a rate from each stand-in", {
  cast: { visitor: Blueprint.anyone },
  steps: (s) => [
    s.step("pricing's stand-in answers", s.visitor.run(quote, { pair: "EURUSD", amount: "100" }), expect((a) => a.rate).toBe("rates-stand-1.0842")),
    s.step("fx-backup's stand-in answers", s.visitor.run(backup, { pair: "GBPUSD", amount: "7" }), expect((a) => a.rate).toBe("fx-rates-stand-1.0842")),
  ],
});
`;

// Each package, the name it is mounted under, and how its stand-in stands. `fx-rates` is mounted as `fx-backup`, so a
// name taken from the package, or kept with its dash, is wrong.
const ADAPTERS = {
  rates: { mount: "pricing", stand: 'Stand.process("check 08\'s stand-in for rates")' },
  "fx-rates": { mount: "fx-backup", stand: 'Stand.process("check 08\'s stand-in for fx-rates")' },
  open: { mount: "open", stand: "Stand.none" },
  sandbox: { mount: "sandbox", stand: 'Stand.vendor("a vendor\'s sandbox, which no process stands in for")' },
} as const;

interface App { readonly root: string; readonly log: string; readonly remove: () => void }
const apps: Array<App> = [];
// A wrong build may leave stand-ins running: whatever a stand-in logged is stopped before its copy goes.
afterEach(() => {
  for (const app of apps.splice(0)) {
    for (const e of entriesOf(app.log)) for (const pid of [e.pid, e.child]) if (pid !== undefined && alive(pid)) process.kill(pid, "SIGKILL");
    app.remove();
  }
});

const ortho = (root: string, ...args: ReadonlyArray<string>) => {
  const said = spawnSync(process.execPath, [cli, ...args, "--root", root], { cwd: root, encoding: "utf8", maxBuffer: 64 * 1024 * 1024, timeout: 240_000 });
  return { status: said.status, out: `${said.stdout}${said.stderr}` };
};
const succeeds = (root: string, ...args: ReadonlyArray<string>) => {
  const said = ortho(root, ...args);
  expect(said.status, `ortho ${args.join(" ")}:\n${said.out}`).toBe(0);
  return said;
};

/**
 * A copy of acme with the four adapters generated, installed and mounted. With `calls`, `rate.quote` (pricing) and `rate.backup`
 * (fx-backup) call them, and the journey "a rate from each stand-in" runs both; without, nothing calls them, so the app generates
 * whatever the call steps can do. `fault` names the plugin whose stand-in exits before it listens, or never says where.
 */
const app = (options: { readonly calls?: boolean; readonly fault?: { readonly plugin: string } & Fault } = {}): App => {
  const copy = copyOf(acme);
  const log = join(copy.root, "..", "stands.log");
  const made = { ...copy, log };
  apps.push(made);
  const { root } = copy;
  // The copy's @orthograph is acme's, linked whole: make it a folder of links, so the generated plugins can join it.
  const scope = join(root, "node_modules/@orthograph");
  rmSync(scope);
  mkdirSync(scope);
  for (const entry of readdirSync(join(acme, "node_modules/@orthograph"))) symlinkSync(join(acme, "node_modules/@orthograph", entry), join(scope, entry));
  const specs = join(root, ".specs");
  mkdirSync(specs);
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { dependencies: Record<string, string> };
  mkdirSync(join(root, "blueprint/adapters"), { recursive: true });
  for (const [name, { mount, stand }] of Object.entries(ADAPTERS)) {
    writeFileSync(join(specs, `${name}.json`), JSON.stringify(spec(name[0]!.toUpperCase() + name.slice(1))));
    succeeds(root, "new", "adapter", name, "--from-openapi", join(specs, `${name}.json`));
    const plugin = join(root, "plugins", name);
    // Every package names a stand-in; only the model's `Stand.process` says to run one.
    writeFileSync(join(plugin, "stand.mjs"), standInOf(name, log, options.fault?.plugin === name ? options.fault : undefined));
    const manifest = JSON.parse(readFileSync(join(plugin, "package.json"), "utf8")) as { orthograph: Record<string, unknown> };
    manifest.orthograph["standIn"] = "stand.mjs";
    writeFileSync(join(plugin, "package.json"), JSON.stringify(manifest, null, 2));
    if (stand !== "Stand.none") {
      const written = join(plugin, "src/written.ts");
      const before = readFileSync(written, "utf8");
      const after = before.replace("export const standIn = Stand.none;", `export const standIn = ${stand};`);
      expect(after, `${written} scaffolds \`export const standIn = Stand.none;\``).not.toBe(before);
      writeFileSync(written, after);
    }
    symlinkSync(plugin, join(scope, name));
    pkg.dependencies[`@orthograph/${name}`] = "0.0.0";
    writeFileSync(join(root, `blueprint/adapters/${mount}.ts`), mountOf(name));
  }
  writeFileSync(join(root, "package.json"), JSON.stringify(pkg, null, 2));
  if (options.calls === true) {
    mkdirSync(join(root, "blueprint/things/rate/verbs"), { recursive: true });
    writeFileSync(join(root, "blueprint/things/rate/thing.ts"), THING);
    writeFileSync(join(root, "blueprint/things/rate/verbs/quote.ts"), verbOf("pricing", "rates"));
    writeFileSync(join(root, "blueprint/things/rate/verbs/backup.ts"), verbOf("fx-backup", "fx-rates"));
    succeeds(root, "generate");
    mkdirSync(join(root, "src/rate"), { recursive: true });
    writeFileSync(join(root, "src/rate/quote.ts"), handlerOf("quote", "rates"));
    writeFileSync(join(root, "src/rate/backup.ts"), handlerOf("backup", "fx-rates"));
    writeFileSync(join(root, "journeys/a-rate-from-each-stand-in.ts"), JOURNEY);
  }
  succeeds(root, "generate");
  return made;
};

interface Entry {
  readonly plugin: string;
  readonly event: "start" | "request" | "refused" | "silent" | "flooded";
  readonly cwd?: string;
  readonly args?: ReadonlyArray<string>;
  readonly pid?: number;
  readonly child?: number;
  readonly dirThere?: boolean;
  readonly method?: string;
  readonly url?: string;
  readonly authorization?: string | null;
}
const entriesOf = (log: string): ReadonlyArray<Entry> =>
  existsSync(log) ? readFileSync(log, "utf8").split("\n").filter((l) => l !== "").map((l) => JSON.parse(l) as Entry) : [];
const alive = (pid: number) => { try { process.kill(pid, 0); return true; } catch { return false; } };

/**
 * `ortho prove` of one journey, in a world of its own. Its exit is acme's whole verdict (`--only` still judges every operation's
 * evals, and most are reached by no journey), so what a test reads is the journey's own line.
 */
const prove = (root: string, journey: string) => ortho(root, "prove", "--env", "local", "--only", journey);
const HEALTH = /^journey health is up ✔ 1\/1 steps$/m;
/** What prove says when it reuses `ortho dev`'s world (m1 check 30's line). */
const REUSING = /^prove: reusing the world of ortho dev at /m;

const freePort = () => new Promise<number>((found) => {
  const server = createServer();
  server.listen(0, "127.0.0.1", () => { const { port } = server.address() as { port: number }; server.close(() => found(port)); });
});
/** `ortho dev`, started as a user does, ready once its world answers (m1 check 30's way). */
const startDev = async (root: string) => {
  const port = await freePort();
  const child = spawn(process.execPath, [cli, "dev", "--root", root, "--port", String(port)], { cwd: root, stdio: "ignore" });
  for (let i = 0; i < 480; i++) {
    if (child.exitCode !== null) throw new Error("ortho dev exited before its world answered");
    if (await fetch(`http://127.0.0.1:${port}/_world/health`).then((r) => r.ok, () => false)) return child;
    await new Promise((r) => setTimeout(r, 250));
  }
  child.kill("SIGTERM");
  throw new Error(`ortho dev's world at ${port} never answered`);
};
const stopDev = async (child: ChildProcess) => {
  if (child.exitCode !== null) return;
  const exited = new Promise<void>((r) => child.once("exit", () => r()));
  child.kill("SIGTERM");
  await Promise.race([exited, new Promise((r) => setTimeout(r, 30_000))]);
  if (child.exitCode === null) child.kill("SIGKILL");
};

describe("08 prove stands up a mount's process stand-in", () => {
  it("runs node <entry> --port 0 --dir <state>/stands/<mount> once for each process stand-in, its folder there, and none for a mount without one", () => {
    const { root, log } = app();
    const proved = prove(root, "health is up");
    expect(proved.out).toMatch(HEALTH);
    const starts = entriesOf(log).filter((e) => e.event === "start");
    expect(starts.map((e) => ({ plugin: e.plugin, args: e.args, dirThere: e.dirThere })).sort((a, b) => a.plugin.localeCompare(b.plugin)), proved.out).toEqual([
      { plugin: "fx-rates", args: ["--port", "0", "--dir", join(root, ".ortho/prove/stands/fx-backup")], dirThere: true },
      { plugin: "rates", args: ["--port", "0", "--dir", join(root, ".ortho/prove/stands/pricing")], dirThere: true },
    ]);
    // Each runs in its own package's folder, as `e2e/superagent/servers.ts` runs one.
    expect(Object.fromEntries(starts.map((e) => [e.plugin, e.cwd])), proved.out).toEqual({ "fx-rates": realpathSync(join(root, "plugins/fx-rates")), rates: realpathSync(join(root, "plugins/rates")) });
  });

  it("stops each stand-in and every process it started once the world ends: none is running after prove exits", () => {
    const { root, log } = app();
    const proved = prove(root, "health is up");
    const starts = entriesOf(log).filter((e) => e.event === "start");
    // A build that starts no stand-in leaves nothing running too: the stopping is judged only on stand-ins that ran.
    expect(starts.map((e) => e.plugin).sort(), proved.out).toEqual(["fx-rates", "rates"]);
    const left = starts.flatMap((e) => [e.pid!, e.child!]).filter(alive);
    for (const pid of left) process.kill(pid, "SIGKILL");
    expect(left, "stand-in processes, or processes they started, still running after prove exited (their ids, now killed)").toEqual([]);
    nothingRunning(root);
  });

  // Each mount in turn, so a build that stops only the stand-ins started before the failing one is seen; an exit 0 is a failure too.
  for (const { plugin, mount, exit } of [{ plugin: "rates", mount: "pricing", exit: 3 }, { plugin: "fx-rates", mount: "fx-backup", exit: 0 }]) {
    it(`a stand-in that exits ${exit} before it says where it listens fails prove at once, naming the mount (${mount}), and leaves nothing running`, () => {
      const { root, log } = app({ fault: { plugin, refuse: exit } });
      const began = performance.now();
      const proved = prove(root, "health is up");
      const seconds = (performance.now() - began) / 1000;
      expect(entriesOf(log).filter((e) => e.event === "refused").map((e) => e.plugin), proved.out).toEqual([plugin]);
      // No world ran without its stand-in: the journey never ran, and what prove said names the mount (no other line here does).
      expect(proved.status, proved.out).not.toBe(0);
      expect(proved.out).not.toMatch(/^journey health is up/m);
      expect(proved.out).toContain(mount);
      // The exit itself fails prove, not the 60 s wait for a stand-in that says nothing (about 13 s here).
      expect(seconds, proved.out).toBeLessThan(45);
      const left = entriesOf(log).filter((e) => e.event === "start").flatMap((e) => [e.pid!, e.child!]).filter(alive);
      for (const pid of left) process.kill(pid, "SIGKILL");
      expect(left, "processes still running after prove failed (their ids, now killed)").toEqual([]);
      nothingRunning(root);
    });
  }

  it("a stand-in that never says where it listens fails prove within 60 s of starting it, naming the mount, and leaves nothing running", () => {
    const { root, log } = app({ fault: { plugin: "rates", silent: true } });
    const began = performance.now();
    const proved = prove(root, "health is up");
    const seconds = (performance.now() - began) / 1000;
    expect(entriesOf(log).filter((e) => e.event === "silent").map((e) => e.plugin), proved.out).toEqual(["rates"]);
    expect(proved.status, proved.out).not.toBe(0);
    expect(proved.out).not.toMatch(/^journey health is up/m);
    expect(proved.out).toContain("pricing");
    // 60 s for the stand-in, and room for the rest of a prove that never ran a journey.
    expect(seconds, proved.out).toBeLessThan(150);
    const left = entriesOf(log).filter((e) => e.event === "start").flatMap((e) => [e.pid!, e.child!]).filter(alive);
    for (const pid of left) process.kill(pid, "SIGKILL");
    expect(left, "processes still running after prove failed (their ids, now killed)").toEqual([]);
    nothingRunning(root);
  });
});

describe("08 a model with a process stand-in gets a world of its own", () => {
  it("with ortho dev's world warm, prove still starts a world of its own and its stand-ins, and never says it reuses dev's", async () => {
    const { root, log } = app();
    const dev = await startDev(root);
    let proved: { readonly status: number | null; readonly out: string };
    try {
      proved = prove(root, "health is up");
    } finally { await stopDev(dev); }
    expect(proved.out).not.toMatch(REUSING);
    expect(proved.out).toMatch(HEALTH);
    expect(entriesOf(log).filter((e) => e.event === "start").map((e) => e.plugin).sort(), proved.out).toEqual(["fx-rates", "rates"]);
    nothingRunning(root);
  });
});

describe("08 a call step in prove's world reaches the mount's stand-in", () => {
  it("each mount's call reaches its own stand-in at the address it said, with world-<mount> as its key", () => {
    const { root, log } = app({ calls: true });
    const proved = prove(root, "a rate from each stand-in");
    const requests = entriesOf(log).filter((e) => e.event === "request").map((e) => ({ plugin: e.plugin, method: e.method, url: e.url, authorization: e.authorization, dirThere: e.dirThere }));
    // The folder is still there when the call comes (a build that starts the stand-ins before the world's state is wiped loses it).
    expect(requests.sort((a, b) => a.plugin.localeCompare(b.plugin)), proved.out).toEqual([
      { plugin: "fx-rates", method: "GET", url: "/quotes/GBPUSD?amount=7", authorization: "Bearer world-fx-backup", dirThere: true },
      { plugin: "rates", method: "GET", url: "/quotes/EURUSD?amount=100", authorization: "Bearer world-pricing", dirThere: true },
    ]);
    // Each stand-in wrote its megabyte after its line and still answered: prove kept reading what it said.
    expect(entriesOf(log).filter((e) => e.event === "flooded").map((e) => e.plugin).sort(), proved.out).toEqual(["fx-rates", "rates"]);
    expect(proved.out).toMatch(/^journey a rate from each stand-in ✔ 2\/2 steps$/m);
    nothingRunning(root);
  });
});
